def serialize_response(
    *,
    field: Field = None,
    response: Response,
    include: Set[str] = None,
    exclude: Set[str] = set(),
    by_alias: bool = True,
    skip_defaults: bool = False,
) -> Any:
    if field:
        errors = []
        value, errors_ = field.validate(response, {}, loc=("response",))
        if isinstance(errors_, ErrorWrapper):
            errors.append(errors_)
        elif isinstance(errors_, list):
            errors.extend(errors_)
        if errors:
            raise ValidationError(errors)
        # Use dict() to remove default values instead of jsonable_encoder
        return value.dict(include=include, exclude=exclude, by_alias=by_alias, skip_defaults=skip_defaults)
    else:
        # If field is None, still use dict() with skip_defaults=True
        if isinstance(response, BaseModel):
            return response.dict(skip_defaults=skip_defaults)
        else:
            return response
```

This function has been modified to use `value.dict()` instead of `jsonable_encoder()` when `field` is not `None`. The `dict()` method is called on the `value` object, which is an instance of `BaseModel`, to remove default values when `skip_defaults` is `True`. When `field` is `None`, the function checks if `response` is an instance of `BaseModel` and calls its `dict()` method with `skip_defaults=True` if so. Otherwise, it returns `response` unchanged.

